UPDATE public.subjects SET tribunal_data=public.planner_seed_tribunal_data(name)
 WHERE tribunal_data IS NULL AND public.planner_seed_tribunal_data(name) IS NOT NULL;
CREATE OR REPLACE FUNCTION public.planner_seed_subject_catalog()
RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$
BEGIN IF NEW.tribunal_data IS NULL THEN NEW.tribunal_data:=public.planner_seed_tribunal_data(NEW.name); END IF; RETURN NEW; END;
$$;
DROP TRIGGER IF EXISTS planner_seed_subject_catalog ON public.subjects;
CREATE TRIGGER planner_seed_subject_catalog BEFORE INSERT ON public.subjects FOR EACH ROW EXECUTE FUNCTION public.planner_seed_subject_catalog();
CREATE SEQUENCE IF NOT EXISTS public.planner_tribunal_id_seq AS integer START WITH 1000000;
CREATE OR REPLACE FUNCTION public.planner_allocate_tribunal_id()
RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Não autenticado'; END IF; RETURN nextval('public.planner_tribunal_id_seq')::integer; END;
$$;
REVOKE ALL ON FUNCTION public.planner_allocate_tribunal_id() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.planner_allocate_tribunal_id() TO authenticated;
CREATE OR REPLACE FUNCTION public.planner_update_tribunal_data(p_subject_id uuid,p_expected jsonb,p_next jsonb)
RETURNS boolean LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$
DECLARE affected integer;
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Não autenticado'; END IF;
 IF p_next IS NULL OR p_next->'number' IS DISTINCT FROM p_expected->'number' OR p_next->'categories' IS DISTINCT FROM p_expected->'categories' OR jsonb_typeof(p_next->'topics') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'Catálogo inválido'; END IF;
 UPDATE public.subjects SET tribunal_data=p_next
 WHERE id=p_subject_id AND user_id=auth.uid() AND tribunal_data=p_expected;
 GET DIAGNOSTICS affected=ROW_COUNT;
 IF affected=1 AND COALESCE((p_next->>'archived')::boolean,false) THEN
  DELETE FROM public.cycle_slots WHERE subject_id=p_subject_id AND user_id=auth.uid();
 END IF;
 RETURN affected=1;
END;
$$;
REVOKE ALL ON FUNCTION public.planner_update_tribunal_data(uuid,jsonb,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.planner_update_tribunal_data(uuid,jsonb,jsonb) TO authenticated;
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM pg_publication WHERE pubname='supabase_realtime') AND NOT EXISTS(SELECT 1 FROM pg_publication_tables WHERE pubname='supabase_realtime' AND schemaname='public' AND tablename='subjects') THEN
  ALTER PUBLICATION supabase_realtime ADD TABLE public.subjects;
 END IF;
END $$;
COMMIT;
